def bisection_root_bracket(coeffs: list[float], a: float, b: float, tol: float) -> float:
    if len(coeffs) == 0:
        return 0.5 * (a + b)
    left = min(a, b)
    right = max(a, b)
    eps = max(1e-12, abs(tol))
    f_left = 0.0
    for c in reversed(coeffs):
        f_left = f_left * left + c
    f_right = 0.0
    for c in reversed(coeffs):
        f_right = f_right * right + c
    if abs(f_left) <= eps:
        return left
    if abs(f_right) <= eps:
        return right
    for _ in range(60):
        mid = left + 0.5 * (right - left)
        if abs(right - left) <= eps:
            return mid
        f_mid = 0.0
        for c in reversed(coeffs):
            f_mid = f_mid * mid + c
        if abs(f_mid) <= eps:
            return mid
        if f_left > 0.0 and f_mid > 0.0 or (f_left < 0.0 and f_mid < 0.0):
            left = mid
            f_left = f_mid
        else:
            right = mid
            f_right = f_mid
    return left + 0.5 * (right - left)

def brent_dekker_root(coeffs: list[float], a: float, b: float, tol: float) -> float:
    if len(coeffs) == 0:
        return 0.5 * (a + b)
    x0 = min(a, b)
    x1 = max(a, b)
    eps = max(1e-12, abs(tol))
    f0 = 0.0
    for c in reversed(coeffs):
        f0 = f0 * x0 + c
    f1 = 0.0
    for c in reversed(coeffs):
        f1 = f1 * x1 + c
    x2 = x0
    f2 = f0
    for _ in range(50):
        if abs(f1) <= eps or abs(x1 - x0) <= eps:
            return x1
        if abs(f0 - f2) > 1e-14 and abs(f1 - f2) > 1e-14:
            s0 = x0 * f1 * f2 / ((f0 - f1) * (f0 - f2))
            s1 = x1 * f0 * f2 / ((f1 - f0) * (f1 - f2))
            s2 = x2 * f0 * f1 / ((f2 - f0) * (f2 - f1))
            trial = s0 + s1 + s2
        else:
            denom = f1 - f0
            trial = x1 - f1 * (x1 - x0) / (denom if abs(denom) > 1e-14 else 1e-14)
        if trial < min(x0, x1) or trial > max(x0, x1):
            trial = 0.5 * (x0 + x1)
        x2 = x1
        f2 = f1
        x1 = trial
        f1 = 0.0
        for c in reversed(coeffs):
            f1 = f1 * x1 + c
    return x1

def newton_raphson_step(x: float, fx: float, dfx: float, tol: float) -> float:
    eps = max(1e-14, abs(tol))
    if abs(fx) <= eps:
        return x
    denom = dfx
    if abs(denom) < 1e-12:
        denom = 1e-12 if denom >= 0.0 else -1e-12
    step = fx / denom
    x_new = x - step
    return x_new

def halley_root_step(x: float, fx: float, dfx: float, d2fx: float) -> float:
    if abs(fx) <= 1e-14:
        return x
    df = dfx
    if abs(df) < 1e-12:
        df = 1e-12 if df >= 0.0 else -1e-12
    denom = 2.0 * df * df - fx * d2fx
    if abs(denom) < 1e-14:
        return x - fx / df
    step = 2.0 * fx * df / denom
    return x - step

def ridder_root_find(coeffs: list[float], a: float, b: float, tol: float) -> float:
    if len(coeffs) == 0:
        return 0.5 * (a + b)
    x1 = min(a, b)
    x2 = max(a, b)
    eps = max(1e-12, abs(tol))
    for _ in range(40):
        if abs(x2 - x1) <= eps:
            return 0.5 * (x1 + x2)
        f1 = 0.0
        for c in reversed(coeffs):
            f1 = f1 * x1 + c
        f2 = 0.0
        for c in reversed(coeffs):
            f2 = f2 * x2 + c
        xm = 0.5 * (x1 + x2)
        fm = 0.0
        for c in reversed(coeffs):
            fm = fm * xm + c
        if abs(fm) <= eps:
            return xm
        disc = max(0.0, fm * fm - f1 * f2)
        s = math.sqrt(disc)
        if s < 1e-14:
            return xm
        sign_factor = 1.0 if f1 >= f2 else -1.0
        x_new = xm + (xm - x1) * (sign_factor * fm) / s
        f_new = 0.0
        for c in reversed(coeffs):
            f_new = f_new * x_new + c
        if abs(f_new) <= eps:
            return x_new
        if fm > 0.0 and f_new < 0.0 or (fm < 0.0 and f_new > 0.0):
            x1 = min(xm, x_new)
            x2 = max(xm, x_new)
        elif f1 > 0.0 and f_new < 0.0 or (f1 < 0.0 and f_new > 0.0):
            x2 = x_new
        else:
            x1 = x_new
    return 0.5 * (x1 + x2)

def simpson_adaptive_quad(vals: list[float], h: float) -> float:
    n = len(vals)
    if n < 2:
        return 0.0
    if n == 2:
        return 0.5 * h * (vals[0] + vals[1])
    total = vals[0] + vals[-1]
    for i in range(1, n - 1):
        weight = 4.0 if i % 2 == 1 else 2.0
        total = total + weight * vals[i]
    step = abs(h)
    return total * (step / 3.0)

def neville_polynomial_interpolate(xs: list[float], ys: list[float], x_eval: float) -> float:
    n = min(len(xs), len(ys))
    if n == 0:
        return 0.0
    p = [float(y) for y in ys[:n]]
    for m in range(1, n):
        for i in range(n - m):
            j = i + m
            dx = xs[i] - xs[j]
            if abs(dx) < 1e-14:
                dx = 1e-14 if dx >= 0.0 else -1e-14
            p[i] = ((x_eval - xs[j]) * p[i] + (xs[i] - x_eval) * p[i + 1]) / dx
    return p[0]

def lu_doolittle_decompose(a_mat: list[list[float]], n: int) -> tuple[list[list[float]], list[list[float]]]:
    dim = min(abs(n), len(a_mat))
    if dim == 0:
        return ([], [])
    l_mat = [[1.0 if r == c else 0.0 for c in range(dim)] for r in range(dim)]
    u_mat = [[0.0 for _ in range(dim)] for _ in range(dim)]
    for i in range(dim):
        for k in range(i, dim):
            s = sum((l_mat[i][p] * u_mat[p][k] for p in range(i)))
            val = a_mat[i][k] if k < len(a_mat[i]) else 0.0
            u_mat[i][k] = val - s
        for k in range(i + 1, dim):
            s = sum((l_mat[k][p] * u_mat[p][i] for p in range(i)))
            val = a_mat[k][i] if i < len(a_mat[k]) else 0.0
            piv = u_mat[i][i]
            if abs(piv) < 1e-14:
                piv = 1e-14 if piv >= 0.0 else -1e-14
            l_mat[k][i] = (val - s) / piv
    return (l_mat, u_mat)

def cholesky_banachiewicz_decompose(a_mat: list[list[float]], n: int) -> list[list[float]]:
    dim = min(abs(n), len(a_mat))
    if dim == 0:
        return []
    l_mat = [[0.0 for _ in range(dim)] for _ in range(dim)]
    for i in range(dim):
        for j in range(i + 1):
            s = sum((l_mat[i][k] * l_mat[j][k] for k in range(j)))
            val = a_mat[i][j] if j < len(a_mat[i]) else 0.0
            if i == j:
                diff = max(0.0, val - s)
                l_mat[i][j] = math.sqrt(diff)
            else:
                piv = l_mat[j][j]
                if abs(piv) < 1e-14:
                    piv = 1e-14 if piv >= 0.0 else -1e-14
                l_mat[i][j] = (val - s) / piv
    return l_mat

def gram_schmidt_qr_factorize(a_mat: list[list[float]], m: int, n: int) -> tuple[list[list[float]], list[list[float]]]:
    rows = min(abs(m), len(a_mat))
    if rows == 0:
        return ([], [])
    cols = min(abs(n), len(a_mat[0]))
    if cols == 0:
        return ([], [])
    v_cols = [[a_mat[r][c] for r in range(rows)] for c in range(cols)]
    q_cols = [[0.0 for _ in range(rows)] for _ in range(cols)]
    r_mat = [[0.0 for _ in range(cols)] for _ in range(cols)]
    for i in range(cols):
        norm_sq = sum((v_cols[i][r] * v_cols[i][r] for r in range(rows)))
        norm_v = math.sqrt(norm_sq)
        r_mat[i][i] = norm_v
        if norm_v > 1e-14:
            q_cols[i] = [v_cols[i][r] / norm_v for r in range(rows)]
        else:
            q_cols[i] = [0.0 for _ in range(rows)]
        for j in range(i + 1, cols):
            dot_prod = sum((q_cols[i][r] * v_cols[j][r] for r in range(rows)))
            r_mat[i][j] = dot_prod
            for r in range(rows):
                v_cols[j][r] = v_cols[j][r] - dot_prod * q_cols[i][r]
    q_mat = [[q_cols[c][r] for c in range(cols)] for r in range(rows)]
    return (q_mat, r_mat)

def householder_reflector_vector(x_vec: list[float]) -> list[float]:
    n = len(x_vec)
    if n == 0:
        return []
    norm_sq = sum((val * val for val in x_vec))
    sigma = math.sqrt(norm_sq)
    if sigma < 1e-15:
        return [1.0] + [0.0] * (n - 1)
    sign = 1.0 if x_vec[0] >= 0.0 else -1.0
    v = [float(val) for val in x_vec]
    v[0] = v[0] + sign * sigma
    v_norm = math.sqrt(sum((val * val for val in v)))
    if v_norm < 1e-15:
        return [1.0] + [0.0] * (n - 1)
    unit_v = [val / v_norm for val in v]
    return unit_v

def givens_rotation_matrix_entries(a: float, b: float) -> tuple[float, float]:
    scale_a = float(a)
    scale_b = float(b)
    if abs(scale_b) < 1e-15:
        return (1.0, 0.0)
    if abs(scale_b) > abs(scale_a):
        tau = scale_a / scale_b
        s = 1.0 / math.sqrt(1.0 + tau * tau)
        c = s * tau
    else:
        tau = scale_b / scale_a
        c = 1.0 / math.sqrt(1.0 + tau * tau)
        s = c * tau
    return (c, s)

def power_iteration_dominant_eigen(a_mat: list[list[float]], v_init: list[float], iters: int) -> tuple[float, list[float]]:
    n = len(v_init)
    if n == 0 or len(a_mat) < n:
        return (0.0, [])
    norm_v = math.sqrt(sum((x * x for x in v_init)))
    v = [x / norm_v for x in v_init] if norm_v > 1e-14 else [1.0] + [0.0] * (n - 1)
    max_steps = max(1, min(100, abs(iters)))
    for _ in range(max_steps):
        w = [sum((a_mat[r][c] * v[c] for c in range(min(n, len(a_mat[r]))))) for r in range(n)]
        norm_w = math.sqrt(sum((x * x for x in w)))
        if norm_w < 1e-14:
            break
        v = [x / norm_w for x in w]
    av = [sum((a_mat[r][c] * v[c] for c in range(min(n, len(a_mat[r]))))) for r in range(n)]
    eigenval = sum((v[i] * av[i] for i in range(n)))
    return (eigenval, v)

def jacobi_eigenvalue_2x2_sweep(a11: float, a12: float, a22: float) -> tuple[float, float, float, float]:
    if abs(a12) < 1e-14:
        return (a11, a22, 1.0, 0.0)
    tau = (a22 - a11) / (2.0 * a12)
    s_tau = 1.0 if tau >= 0.0 else -1.0
    t = s_tau / (abs(tau) + math.sqrt(1.0 + tau * tau))
    c = 1.0 / math.sqrt(1.0 + t * t)
    s = t * c
    lam1 = a11 - t * a12
    lam2 = a22 + t * a12
    return (lam1, lam2, c, s)

def gauss_seidel_iteration_step(a_mat: list[list[float]], b_vec: list[float], x_vec: list[float]) -> list[float]:
    n = min(len(a_mat), len(b_vec), len(x_vec))
    if n == 0:
        return []
    x = [float(v) for v in x_vec[:n]]
    for i in range(n):
        s1 = sum((a_mat[i][j] * x[j] for j in range(i) if j < len(a_mat[i])))
        s2 = sum((a_mat[i][j] * x[j] for j in range(i + 1, n) if j < len(a_mat[i])))
        diag = a_mat[i][i] if i < len(a_mat[i]) else 1.0
        if abs(diag) < 1e-14:
            diag = 1e-14 if diag >= 0.0 else -1e-14
        x[i] = (b_vec[i] - s1 - s2) / diag
    return x

def conjugate_gradient_step(r_vec: list[float], p_vec: list[float], ap_vec: list[float], alpha: float) -> tuple[list[float], list[float], float]:
    n = min(len(r_vec), len(p_vec), len(ap_vec))
    if n == 0:
        return ([], [], 0.0)
    denom = sum((x * x for x in r_vec[:n]))
    if denom < 1e-15:
        return ([0.0] * n, [0.0] * n, 0.0)
    r_next = [r_vec[i] - alpha * ap_vec[i] for i in range(n)]
    num = sum((x * x for x in r_next))
    beta = num / denom
    p_next = [r_next[i] + beta * p_vec[i] for i in range(n)]
    return (r_next, p_next, beta)

def gmres_givens_arnoldi_step(h_mat: list[list[float]], cs_vec: list[float], sn_vec: list[float], k: int) -> tuple[float, float]:
    idx = max(0, abs(k))
    if idx + 1 >= len(h_mat) or idx >= len(h_mat[idx]):
        return (1.0, 0.0)
    col = [h_mat[r][idx] if idx < len(h_mat[r]) else 0.0 for r in range(idx + 2)]
    n_rot = min(idx, len(cs_vec), len(sn_vec))
    for i in range(n_rot):
        c = cs_vec[i]
        s = sn_vec[i]
        t1 = c * col[i] - s * col[i + 1]
        t2 = s * col[i] + c * col[i + 1]
        col[i] = t1
        col[i + 1] = t2
    a = col[idx]
    b = col[idx + 1]
    if abs(b) < 1e-15:
        return (1.0, 0.0)
    hyp = math.hypot(a, b)
    c_new = a / hyp
    s_new = -b / hyp
    return (c_new, s_new)

def rk45_fehlberg_step(t: float, y: float, h: float, k1: float, k2: float, k3: float, k4: float, k5: float, k6: float) -> tuple[float, float]:
    step = h if abs(h) > 1e-15 else 1e-15
    y4 = y + step * (25.0 / 216.0 * k1 + 1408.0 / 2565.0 * k3 + 2197.0 / 4104.0 * k4 - 1.0 / 5.0 * k5)
    y5 = y + step * (16.0 / 135.0 * k1 + 6656.0 / 12825.0 * k3 + 28561.0 / 56430.0 * k4 - 9.0 / 50.0 * k5 + 2.0 / 55.0 * k6)
    err = abs(y5 - y4)
    return (y4, err)

def crank_nicolson_diffusion_step(u_vec: list[float], r_param: float) -> list[float]:
    n = len(u_vec)
    if n < 2:
        return list(u_vec)
    r = min(1.0, max(0.0, abs(r_param)))
    half_r = 0.5 * r
    rhs = [float(val) for val in u_vec]
    for i in range(1, n - 1):
        diff2 = u_vec[i - 1] - 2.0 * u_vec[i] + u_vec[i + 1]
        rhs[i] = u_vec[i] + half_r * diff2
    return rhs

def upwind_advection_step(u_vec: list[float], c_vel: float, dt: float, dx: float) -> list[float]:
    n = len(u_vec)
    if n < 2:
        return list(u_vec)
    safe_dx = dx if abs(dx) > 1e-14 else 1e-14
    cfl = abs(c_vel) * abs(dt) / abs(safe_dx)
    eff_cfl = min(1.0, cfl)
    u_new = [float(v) for v in u_vec]
    if c_vel >= 0.0:
        for i in range(1, n):
            u_new[i] = u_vec[i] - eff_cfl * (u_vec[i] - u_vec[i - 1])
    else:
        for i in range(n - 1):
            u_new[i] = u_vec[i] - eff_cfl * (u_vec[i + 1] - u_vec[i])
    return u_new

def frobenius_norm_matrix(a_mat: list[list[float]]) -> float:
    max_val = 0.0
    for row in a_mat:
        for x in row:
            if abs(x) > max_val:
                max_val = abs(x)
    if max_val < 1e-15:
        return 0.0
    sum_sq = 0.0
    for row in a_mat:
        for x in row:
            scaled = x / max_val
            sum_sq = sum_sq + scaled * scaled
    norm_f = max_val * math.sqrt(sum_sq)
    return norm_f

def pade_approximant_eval(p_coeffs: list[float], q_coeffs: list[float], x: float) -> float:
    p_val = 0.0
    for c in reversed(p_coeffs):
        p_val = p_val * x + c
    q_val = 0.0
    for c in reversed(q_coeffs):
        q_val = q_val * x + c
    if abs(q_val) < 1e-12:
        return 1000000000000.0 if p_val >= 0.0 else -1000000000000.0
    res = p_val / q_val
    return res
